/**
 * Material for two games, drawn from the lessons: nothing here says more than the lesson it points to.
 *
 * "Sound or weak?" asks the learner to judge an argument a Christian might be tempted to use.
 * "Timeline" asks the learner to put sources and events in order.
 */

export type Verdict = 'sound' | 'overstated' | 'avoid';

export const VERDICTS: { id: Verdict; label: string; meaning: string }[] = [
  { id: 'sound', label: 'Use it', meaning: 'Accurate as stated. The lesson teaches it.' },
  { id: 'overstated', label: 'Overstated', meaning: 'There is something true in it, but it claims too much as stated.' },
  { id: 'avoid', label: 'Leave alone', meaning: 'The lesson says not to use this argument.' },
];

export interface Argument {
  id: string;
  /** The topic whose lesson settles it. */
  topicId: string;
  /** The argument, as someone might put it. */
  claim: string;
  verdict: Verdict;
  /** One or two sentences: why, and what to say instead. */
  why: string;
}

export const ARGUMENTS: Argument[] = [
  // Ancient writers outside the Bible
  { id: 'arg-tacitus', topicId: 'ancient-writers', verdict: 'sound', claim: 'Tacitus, a Roman historian who despised Christians, records that Christ was executed under Pontius Pilate.', why: 'He says so in his Annals, written about AD 116. A hostile writer had no reason to invent it.' },
  { id: 'arg-pliny', topicId: 'ancient-writers', verdict: 'sound', claim: 'About AD 112 a Roman governor reported that Christians sang hymns to Christ “as to a god”.', why: 'Pliny the Younger wrote this to the emperor Trajan after questioning former Christians.' },
  { id: 'arg-historians-resurrection', topicId: 'ancient-writers', verdict: 'overstated', claim: 'Roman and Jewish historians prove that Jesus rose from the dead.', why: 'They confirm the outline: that he lived, was executed under Pilate and was soon worshipped. They do not prove the resurrection.' },
  { id: 'arg-testimonium', topicId: 'ancient-writers', verdict: 'avoid', claim: 'Josephus, a Jewish historian, wrote of Jesus, “He was the Christ.”', why: 'Most scholars think Christian copyists touched up that paragraph. Use his short mention of James, “the brother of Jesus, who was called Christ”.' },
  { id: 'arg-thallus', topicId: 'ancient-writers', verdict: 'avoid', claim: 'Thallus, a first-century pagan, confirms the darkness at the crucifixion.', why: 'His work is lost. The remark reaches us third-hand, through a Christian writer preserved by a much later chronicler.' },

  // Archaeology and the Bible
  { id: 'arg-proves-bible', topicId: 'archaeology-and-the-bible', verdict: 'overstated', claim: 'Archaeology proves the Bible.', why: 'It has confirmed a great deal, raised some hard questions, and left most things untouched.' },
  { id: 'arg-tel-dan', topicId: 'archaeology-and-the-bible', verdict: 'sound', claim: 'An inscription found at Tel Dan refers to the “House of David”.', why: 'That is how most scholars read it, and it comes from outside the Bible.' },
  { id: 'arg-pilate-stone', topicId: 'archaeology-and-the-bible', verdict: 'sound', claim: 'A stone found at Caesarea in 1961 names Pontius Pilate as prefect of Judea.', why: 'It was dug up by professional archaeologists and published.' },
  { id: 'arg-chariot-wheels', topicId: 'archaeology-and-the-bible', verdict: 'avoid', claim: 'Chariot wheels from Pharaoh’s army have been found in the Red Sea.', why: 'The claim comes from amateur explorers, not from published excavations.' },
  { id: 'arg-jericho', topicId: 'archaeology-and-the-bible', verdict: 'avoid', claim: 'The fallen walls of Jericho prove Joshua’s conquest.', why: 'Most archaeologists date that destruction too early for Joshua. The lesson calls it an open question and says not to use Jericho as a proof.' },
  { id: 'arg-exodus-confirmed', topicId: 'archaeology-and-the-bible', verdict: 'overstated', claim: 'Archaeology has confirmed the exodus.', why: 'No Egyptian text mentions it and no camp sites have been found in Sinai. The lesson claims only that the story has Egyptian features and that Israel is named in Canaan by about 1208 BC.' },
  { id: 'arg-merneptah', topicId: 'archaeology-and-the-bible', verdict: 'sound', claim: 'An Egyptian monument of about 1208 BC is the earliest mention of Israel outside the Bible.', why: 'It is the victory monument of Pharaoh Merneptah, found at Thebes in 1896.' },

  // The Quran's text and sources
  { id: 'arg-quran-changed', topicId: 'islam-quran-manuscripts', verdict: 'overstated', claim: 'The early manuscripts show that the Quran has been changed beyond recognition.', why: 'Its text has been stable since early in Islam’s history. The evidence only tells against “identical to the last letter”.' },
  { id: 'arg-sanaa', topicId: 'islam-quran-manuscripts', verdict: 'sound', claim: 'The erased lower text of the Sana‘a palimpsest differs from the standard Quran in words and phrases.', why: 'Sadeghi and Goudarzi, who edited it, concluded that it belongs to a different line of text from the one Uthman standardised; a later editor, Asma Hilali, disagrees.' },
  { id: 'arg-clay-birds', topicId: 'islam-quran-sources', verdict: 'sound', claim: 'The story of the boy Jesus making birds of clay is found in a book of legends older than the Quran.', why: 'It comes from the Infancy Gospel of Thomas, a second-century collection of legends.' },
  { id: 'arg-hadith-both-ways', topicId: 'islam-hadith-reliability', verdict: 'avoid', claim: 'The hadith are worthless, and al-Bukhari himself proves that verses of the Quran were lost.', why: 'You cannot call the hadith unreliable and then rest your case on one. Argue from inside Islam’s own sources or not at all.' },
  { id: 'arg-satanic-verses', topicId: 'islam-muhammad-tested', verdict: 'overstated', claim: 'The “Satanic verses” are an established fact that Muslim scholars accept.', why: 'Early Muslim historians report the story, but most Muslim scholars today reject it. Present it as what those sources report, not as agreed fact.' },

  // Early writers outside Islam
  { id: 'arg-never-existed', topicId: 'islam-outside-writers', verdict: 'avoid', claim: 'Muhammad never existed. The Arabs invented him later.', why: 'A Syriac chronicler names him about 640, within ten years of his death. Very few historians doubt that he lived.' },
  { id: 'arg-thomas-presbyter', topicId: 'islam-outside-writers', verdict: 'sound', claim: 'A Christian chronicler names Muhammad within about ten years of his death.', why: 'Thomas the Presbyter, about 640, records a battle between the Romans and “the Arabs of Muhammad”.' },
  { id: 'arg-alive-634', topicId: 'islam-outside-writers', verdict: 'overstated', claim: 'Early Christian writers prove that Muhammad was still alive when Palestine was invaded in 634.', why: 'Several seem to assume it, but most historians keep the traditional date of his death, 632. Say only that the earliest witnesses do not simply repeat the later story.' },
  { id: 'arg-biography-late', topicId: 'islam-outside-writers', verdict: 'sound', claim: 'The earliest surviving biography of Muhammad was written more than a century after he died.', why: 'Ibn Ishaq died in 767, and his book survives mainly in the edition of Ibn Hisham, who died about 833.' },
  { id: 'arg-quran-late', topicId: 'islam-outside-writers', verdict: 'avoid', claim: 'The Quran was put together about two hundred years after Muhammad.', why: 'Leaves of the Quran have been dated by radiocarbon to the seventh century, which rules that out.' },
  { id: 'arg-no-escape', topicId: 'islam-outside-writers', verdict: 'sound', claim: 'No surviving writer of the first century, friend or enemy, says that Jesus escaped the cross.', why: 'Paul and the four Gospels report the crucifixion, and Tacitus records the execution under Pilate.' },

  // Archaeology and the origins of Islam
  { id: 'arg-petra', topicId: 'islam-archaeology', verdict: 'avoid', claim: 'The first mosques face Petra, so Islam really began there.', why: 'Specialists have not accepted it. Early mosques were lined up by the sun and the cardinal directions, not by calculation.' },
  { id: 'arg-mecca-absent', topicId: 'islam-archaeology', verdict: 'avoid', claim: 'Mecca did not exist in Muhammad’s time.', why: 'The Quran names it, and the Quran is early. What can be questioned is the picture of Mecca as a great centre of trade.' },
  { id: 'arg-silence-invented', topicId: 'islam-archaeology', verdict: 'avoid', claim: 'No coin or inscription calls Muhammad God’s messenger for sixty years, so he was made up afterwards.', why: 'The silence is real, but outside writers name him by about 640. It shows only that the public form of Islam took shape over time.' },
  { id: 'arg-mecca-unmentioned', topicId: 'islam-archaeology', verdict: 'overstated', claim: 'No writer outside Arabia mentions Mecca before Islam.', why: 'None clearly does. But Ptolemy’s “Macoraba” is still identified with Mecca by many historians, so say “clearly”.' },
  { id: 'arg-arabia-monotheist', topicId: 'islam-archaeology', verdict: 'sound', claim: 'Inscriptions show Jewish and Christian belief in Arabia long before Muhammad.', why: 'In Yemen the inscriptions to the old gods stop about AD 380, and God is soon called “the Merciful”.' },
  { id: 'arg-abraha-disproves', topicId: 'islam-archaeology', verdict: 'overstated', claim: 'Abraha’s inscription disproves the Quran’s story of the elephant.', why: 'It records a campaign in 552 and does not mention Mecca. It cannot confirm the story, and it cannot disprove it either.' },
  { id: 'arg-dome', topicId: 'islam-archaeology', verdict: 'sound', claim: 'Islam’s first great monument, the Dome of the Rock, declares that God has no son.', why: 'Much of its inscription, dated 691–2, is addressed to Christians and denies that Jesus is the Son of God.' },

  // The Night Journey
  { id: 'arg-ascent-impossible', topicId: 'islam-night-journey', verdict: 'avoid', claim: 'Nobody can be taken up to heaven, so the Night Journey is impossible.', why: 'Christians believe that Elijah was taken up and that Jesus ascended. The question is evidence, not possibility.' },
  { id: 'arg-no-witness', topicId: 'islam-night-journey', verdict: 'sound', claim: 'Nobody witnessed the Night Journey, so it cannot be a reason to believe that Muhammad was a prophet.', why: 'It is believed on his word. The ascension of Jesus, by contrast, was watched by the apostles.' },
  { id: 'arg-arda-viraf', topicId: 'islam-night-journey', verdict: 'avoid', claim: 'The Night Journey was copied from the Persian book of Arda Viraf.', why: 'That book, in the form we have it, was written down after the rise of Islam, so it cannot be shown to be a source.' },
  { id: 'arg-aisha-dream', topicId: 'islam-night-journey', verdict: 'overstated', claim: 'Aisha was there that night, and she said it was only a dream.', why: 'She did not yet live in Muhammad’s house. The earliest biography quotes her as saying his body stayed where it was, and sets that beside the other view.' },
  { id: 'arg-ascent-stories', topicId: 'islam-night-journey', verdict: 'sound', claim: 'Stories of a holy man led up through seven heavens were told before Islam.', why: 'The Ascension of Isaiah, a Christian work of about the second century, is one. This shows the form was known, not that any book was copied.' },

  // The Farthest Mosque
  { id: 'arg-mosque-not-built', topicId: 'islam-farthest-mosque', verdict: 'avoid', claim: 'The al-Aqsa Mosque was built long after Muhammad died, so the Quran’s “farthest mosque” is a mistake.', why: 'The Arabic word means a place of prostration, not necessarily a building. The mosque was named after the verse.' },
  { id: 'arg-jerusalem-unnamed', topicId: 'islam-farthest-mosque', verdict: 'sound', claim: 'The Quran never names Jerusalem.', why: 'That the “farthest mosque” is in Jerusalem comes from the hadith and the commentators.' },
  { id: 'arg-forty-years', topicId: 'islam-farthest-mosque', verdict: 'sound', claim: 'A hadith in al-Bukhari puts forty years between the building of the Sacred Mosque and of al-Aqsa.', why: 'The Quran credits the Kaaba to Abraham, and the temple was Solomon’s, about a thousand years later. Muslim scholars answer that it means earlier foundations.' },
  { id: 'arg-heavenly-agreed', topicId: 'islam-farthest-mosque', verdict: 'overstated', claim: 'Historians agree that the “farthest mosque” first meant a sanctuary in heaven.', why: 'Many Western scholars have argued it, but others disagree, and the earliest surviving Muslim commentaries read it as Jerusalem.' },
  // Foundations lessons
  { id: 'arg-true-for-everyone', topicId: 'truth-and-relativism', verdict: 'sound', claim: 'Either Jesus rose from the dead or he did not, so the claim is true for everyone or for no one.', why: 'It is a claim about something that happened or did not, like which pill will cure an infection. It is not a matter of taste, like which ice cream is best.' },
  { id: 'arg-religions-contradict', topicId: 'truth-and-relativism', verdict: 'overstated', claim: 'The religions contradict one another, which proves that one of them must be true.', why: 'They cannot all be true, but they could all be wrong. The contradictions show only that they are not “the same underneath”.' },
  { id: 'arg-guessing-motives', topicId: 'truth-and-relativism', verdict: 'avoid', claim: 'You only reject Christianity because you do not want Jesus to have a claim on your life.', why: 'A motive explains why a person leans one way; it cannot tell us who is right. Look at the evidence together and do not trade guesses about motives.' },
  { id: 'arg-everything-has-cause', topicId: 'existence-of-god', verdict: 'overstated', claim: 'Everything needs a cause, so the universe must have one.', why: 'The premise is only that whatever begins to exist needs a cause. Put as “everything”, it invites the reply, “Then who caused God?”' },
  { id: 'arg-atheists-not-moral', topicId: 'existence-of-god', verdict: 'avoid', claim: 'Without belief in God, a person cannot be moral or know right from wrong.', why: 'The lesson says the moral argument is not that. It is about what makes moral claims objectively true, not about whether unbelievers can know or do good.' },
  { id: 'arg-lemaitre', topicId: 'existence-of-god', verdict: 'sound', claim: 'The Big Bang theory was first proposed by a physicist who was also a Catholic priest.', why: 'He was Georges Lemaître. Fred Hoyle, who gave the theory its name, disliked the idea of a beginning and defended an eternal steady-state universe for years.' },
  { id: 'arg-laws-describe', topicId: 'science-and-faith', verdict: 'sound', claim: 'The laws of nature describe what happens when nothing from outside nature steps in; they cannot tell us whether anything ever does.', why: 'So a miracle is not nature going wrong. It is the Author of nature acting within it, and the question becomes one of evidence in each case.' },
  { id: 'arg-god-of-gaps', topicId: 'science-and-faith', verdict: 'avoid', claim: 'Science cannot say what caused the Big Bang, so it must have been God.', why: '“We do not know, therefore God” is a gap argument, and the lesson calls it a bad one. Argue from what we can explain: a universe that began, is orderly and can be understood.' },
  { id: 'arg-christianity-made-science', topicId: 'science-and-faith', verdict: 'overstated', claim: 'Christianity produced modern science, and nobody but Christians could have done it.', why: 'The Greeks, the Islamic world and China did science too. The claim is narrower: the pioneers of modern science in Europe gave theological reasons for what they were doing.' },
  { id: 'arg-manuscript-count', topicId: 'reliability-of-scripture', verdict: 'overstated', claim: 'We have nearly six thousand Greek manuscripts of the New Testament, and that number alone proves the text is sound.', why: 'About 5,300 survive, and most are medieval. The raw number matters less than the early witnesses, such as the papyri and the great fourth-century codices.' },
  { id: 'arg-three-witnesses-verse', topicId: 'reliability-of-scripture', verdict: 'avoid', claim: 'The older Bibles’ wording of 1 John 5:7, “the Father, the Word, and the Holy Spirit”, proves the Trinity.', why: 'Those words are absent from the early Greek manuscripts and modern Bibles leave them out. The Trinity is taught in Matthew 28:19 and John 1:1.' },
  { id: 'arg-gallio', topicId: 'reliability-of-scripture', verdict: 'sound', claim: 'An inscription found at Delphi confirms the title Luke gives Gallio, “proconsul of Achaia”.', why: 'It also dates his term to about AD 51. Writers who are careful about what we can check have earned a hearing on what we cannot.' },
  { id: 'arg-nicaea-canon', topicId: 'how-we-got-the-bible', verdict: 'sound', claim: 'The Council of Nicaea made no decision about which books belong in the Bible.', why: 'It met to answer the teaching of Arius about the deity of Christ.' },
  { id: 'arg-bible-says-so', topicId: 'how-we-got-the-bible', verdict: 'avoid', claim: 'The Bible is the word of God because it says it is.', why: 'That is circular, and the lesson says it is not the route. Begin with the New Testament as ordinary historical sources, conclude that Jesus rose, and then take his view of Scripture.' },
  { id: 'arg-canon-all-settled', topicId: 'how-we-got-the-bible', verdict: 'overstated', claim: 'Christians have agreed on all twenty-seven books of the New Testament since the second century.', why: 'The four Gospels, Acts, Paul’s letters, 1 Peter and 1 John were not in serious doubt. Books at the edge, such as Hebrews, James, 2 Peter and Revelation, were discussed for longer.' },
  { id: 'arg-echad', topicId: 'disputed-translations', verdict: 'overstated', claim: 'The Hebrew word for “one” in Deuteronomy 6:4 means a unity of several, so the verse teaches the Trinity.', why: 'The lesson says that claims too much: echad is the ordinary word for the number one. The better point is that Paul repeats Israel’s confession with Jesus inside it (1 Corinthians 8:6).' },
  { id: 'arg-romans-9-5', topicId: 'disputed-translations', verdict: 'overstated', claim: 'Romans 9:5 settles the matter: Paul calls Christ “God over all”.', why: 'The first copies had no punctuation, so the sentence can also be ended at “Christ”, and scholars are divided. Use the verse as support and not as your first text.' },
  { id: 'arg-divine-name-nt', topicId: 'disputed-translations', verdict: 'sound', claim: 'No surviving Greek manuscript of the New Testament contains the divine name.', why: 'In every copy we have, where the New Testament writers quote the Old, the word is “Lord” or “God”. Putting “Jehovah” back is a guess about what they wrote.' },
  { id: 'arg-maranatha', topicId: 'identity-of-jesus', verdict: 'sound', claim: 'Paul preserves a prayer to Jesus in Aramaic, the language of the first believers in Jerusalem.', why: 'It is Maranatha, most likely “Come, O Lord!” (1 Corinthians 16:22).' },
  { id: 'arg-i-am-god-words', topicId: 'identity-of-jesus', verdict: 'overstated', claim: 'Jesus said in so many words, “I am God.”', why: 'Not in those words. He said it in ways his hearers could not miss, such as “before Abraham was born, I am!” and “I and the Father are one”, and both times they picked up stones.' },
  { id: 'arg-nicaea-old-belief', topicId: 'identity-of-jesus', verdict: 'sound', claim: 'The Council of Nicaea did not make Jesus divine; even Arius called him God.', why: 'The dispute was over in what sense. The council put an old belief into careful words and did not create it.' },
  { id: 'arg-prophecy-odds', topicId: 'fulfilled-prophecy', verdict: 'avoid', claim: 'The odds against one man fulfilling hundreds of prophecies are astronomical, so Jesus must be the Messiah.', why: 'Such statistics cannot be checked and they invite an argument about arithmetic. A few clear passages, read aloud, are far more persuasive.' },
  { id: 'arg-every-fulfilment', topicId: 'fulfilled-prophecy', verdict: 'overstated', claim: 'Every time the New Testament says a Scripture was fulfilled, a direct prediction came true.', why: 'Sometimes it means that. Sometimes it means a pattern in Israel’s story reached its goal in Jesus, so do not claim every case is the first kind.' },
  { id: 'arg-isaiah-scrolls', topicId: 'fulfilled-prophecy', verdict: 'sound', claim: 'Copies of Isaiah found among the Dead Sea Scrolls were made before Jesus was born.', why: 'So were copies of other prophets, and the Law and the Prophets had been translated into Greek before his time. Whatever these passages say, they said it first.' },
  { id: 'arg-all-apostles-martyrs', topicId: 'resurrection', verdict: 'overstated', claim: 'All the apostles died as martyrs for saying that Jesus rose.', why: 'The evidence is good for Peter, Paul, James the brother of Jesus and James the son of Zebedee. For the rest the accounts are later and less certain, so do not claim more.' },
  { id: 'arg-theft-grants-empty', topicId: 'resurrection', verdict: 'sound', claim: 'The earliest reply on record, that the disciples stole the body, explains an empty tomb and does not deny one.', why: 'People who say a body was stolen are agreeing that it is gone.' },
  { id: 'arg-tomb-guards', topicId: 'resurrection', verdict: 'avoid', claim: 'The guards at the tomb prove that nobody could have taken the body.', why: 'Only Matthew mentions guards and many scholars doubt them. The lesson leaves them out and rests on the charge of theft itself, which grants that the body was gone.' },
  { id: 'arg-jesus-own-claim', topicId: 'jesus-only-way', verdict: 'sound', claim: 'Christians did not invent the idea that Jesus is the only way to God; Jesus said it himself.', why: '“No one comes to the Father except through Me” (John 14:6). So the question is whether Jesus was right, not whether Christians are narrow-minded.' },
  { id: 'arg-never-heard-certain', topicId: 'jesus-only-way', verdict: 'overstated', claim: 'The Bible spells out that nobody who dies without hearing the name of Jesus can be saved.', why: 'No one is saved apart from Christ, but whether God ever saves someone who has not heard the name is a point on which Christians disagree. Scripture’s emphasis is that people need to hear.' },
  { id: 'arg-grandmother', topicId: 'jesus-only-way', verdict: 'avoid', claim: 'Your grandmother was not a Christian, so she is in hell.', why: 'You are not the judge of any individual. Do not soften what Jesus said, and do not go beyond it; say what he offers.' },
  { id: 'arg-gods-plan', topicId: 'problem-of-evil', verdict: 'avoid', claim: 'Said to someone grieving: “It was God’s plan. Everything happens for a reason.”', why: 'The lesson’s reply is, “I will not say it.” The Bible never calls death good; it calls it an enemy, and Jesus wept at his friend’s grave.' },
  { id: 'arg-disaster-punishment', topicId: 'problem-of-evil', verdict: 'avoid', claim: 'That disaster was God’s punishment on the people it struck.', why: 'Jesus contradicted this. Of the eighteen killed by a falling tower he asked whether they were more sinful than the rest, and answered, “No, I tell you” (Luke 13:4-5).' },
  { id: 'arg-free-will-settled', topicId: 'problem-of-evil', verdict: 'overstated', claim: 'Philosophers now agree that the free will defence has solved the problem of evil.', why: 'Many, though not all, agree that it answers the logical problem as it was put in the twentieth century. The evidential problem, from the amount of evil, needs other answers.' },
  { id: 'arg-no-survivors', topicId: 'hard-passages', verdict: 'overstated', claim: '“Left no survivors” is only the sweeping language of ancient war reports, so the conquest is no real difficulty.', why: 'Many scholars do argue that, and the same books show those peoples still living in the land. But it softens the picture without removing the difficulty, so do not lean on it.' },
  { id: 'arg-kidnapping-capital', topicId: 'hard-passages', verdict: 'sound', claim: 'The law of Moses made kidnapping a person in order to sell him a capital crime.', why: 'Exodus 21:16. That is the kidnapping on which the Atlantic slave trade depended.' },
  { id: 'arg-nothing-troubling', topicId: 'hard-passages', verdict: 'avoid', claim: 'Nothing in the conquest of Canaan should trouble anyone who reads it properly.', why: 'These passages are disturbing, and pretending otherwise costs you your credibility. Say, “That troubles me too,” and then give a real answer.' },
  { id: 'arg-ask-for-reasons', topicId: 'having-the-conversation', verdict: 'sound', claim: 'You do not have to refute a claim that nobody has supported; you can ask, “How did you come to that conclusion?”', why: 'The question asks for reasons and gently hands over the burden of proof.' },
  { id: 'arg-never-admit', topicId: 'having-the-conversation', verdict: 'avoid', claim: 'Never admit that you do not know the answer; it weakens your case.', why: '“I don’t know, but I’ll find out” is one of the most persuasive things a Christian can say, because it shows you care more about truth than about winning.' },
  { id: 'arg-argued-into-faith', topicId: 'having-the-conversation', verdict: 'overstated', claim: 'A good enough argument will bring anyone to faith.', why: 'No one is argued into faith; God has to open a person’s heart. Arguments do not create faith, but they clear away what stops people from considering it.' },
  // Islam sub-tracks
  { id: 'arg-two-sahihs', topicId: 'sunni-overview', verdict: 'sound', claim: 'Sunni scholars hold that the hadith collections of al-Bukhari and Muslim are the most authentic books after the Quran.', why: 'Al-Nawawi wrote that the scholars agree on this. Accept it as the Sunni position and hold your friend to what those books contain.' },
  { id: 'arg-every-sunni-apostasy', topicId: 'sunni-overview', verdict: 'overstated', claim: 'Every Sunni wants people who leave Islam to be put to death.', why: 'The four schools did draw that ruling from the hadith, but many Sunnis are troubled by it. The point is what Sunni doctrine ties the believer to, not what each person wants.' },
  { id: 'arg-sunni-made-up-later', topicId: 'sunni-overview', verdict: 'overstated', claim: 'Sunni Islam was made up centuries after Muhammad and has no real link to the first Muslims.', why: 'Sunnis do stand in line with the majority of the early community. What took shape over centuries is what marks Sunni Islam: the schools, the six books and the creeds.' },
  { id: 'arg-pond-hadith', topicId: 'sunni-companions', verdict: 'sound', claim: 'Sahih al-Bukhari reports Muhammad saying that some of his companions will be taken away from him at the Pond on the Last Day.', why: 'It is in the book Sunnis trust most. Be fair about how Sunnis read it: the standard answer is that these were the tribes who left Islam after Muhammad died.' },
  { id: 'arg-shia-were-right', topicId: 'sunni-companions', verdict: 'avoid', claim: 'The Shia are right: Abu Bakr and Umar took what belonged to Ali and Fatima.', why: 'You do not need to decide who was right, and you should not side with the Shia against a Sunni friend. Notice only what Bukhari records: the best generation was divided from the first day.' },
  { id: 'arg-salafi-terrorist', topicId: 'sunni-salafi-sufi', verdict: 'avoid', claim: 'Salafis are extremists, so a Salafi neighbour probably sympathises with terrorism.', why: 'The great majority of Salafis are not jihadists. To treat a Salafi neighbour as a terrorist is false and unjust.' },
  { id: 'arg-divisions-prove-false', topicId: 'sunni-salafi-sufi', verdict: 'overstated', claim: 'Muslims are split into streams that accuse one another of unbelief, and that proves Islam is false.', why: 'The accusations are real, but Christians have their own divisions to answer for. Use the point only to set aside the claim that Islam is one while Christianity is hopelessly divided.' },
  { id: 'arg-amman-message', topicId: 'sunni-salafi-sufi', verdict: 'sound', claim: 'In 2005 Muslim scholars had to declare that a Sufi or a Salafi may not be called an apostate, which shows such charges were being made.', why: 'That is the Amman Message, and nobody issues such a statement unless the thing is happening. Give the leaders credit for trying to stop it.' },
  { id: 'arg-shia-backs-iran', topicId: 'shia-overview', verdict: 'avoid', claim: 'A Shia Muslim supports the government of Iran.', why: 'Never assume this. Not all Shia scholars accept the doctrine by which a cleric rules Iran; al-Khoei of Najaf, the leading jurist of his day, did not.' },
  { id: 'arg-ayatollah-everything', topicId: 'shia-overview', verdict: 'overstated', claim: 'A Shia must follow his ayatollah in everything, including what to believe.', why: 'Emulation covers law, not the roots of belief. Ayatollah Sistani’s own manual says a Muslim’s belief in the fundamentals must rest on his own insight.' },
  { id: 'arg-eleventh-imam-son', topicId: 'shia-overview', verdict: 'sound', claim: 'Not all the followers of the eleventh Imam accepted that he had left a son.', why: 'An early Shia writer counted fourteen factions after his death, and the Imam’s own brother claimed the Imamate. The Twelver view prevailed and the other groups died out.' },
  { id: 'arg-defend-abu-bakr', topicId: 'shia-imamate', verdict: 'avoid', claim: 'Muhammad named no successor, so the Muslims were right to choose Abu Bakr.', why: 'That is the Sunni case, and a Christian has no reason to argue it. Stay an outsider who listens to both accounts and asks what they show.' },
  { id: 'arg-quran-silent-on-ali', topicId: 'shia-imamate', verdict: 'sound', claim: 'The Quran never names Ali and never mentions twelve Imams, though Twelvers count the Imamate among the roots of religion.', why: 'It names Muhammad’s adopted son Zayd and his uncle Abu Lahab, yet is silent here. Each verse the Shia quote needs a report from outside the Quran to show that it means Ali.' },
  { id: 'arg-imam-too-old', topicId: 'shia-imamate', verdict: 'avoid', claim: 'Nobody can live for more than a thousand years, so the hidden Imam cannot exist.', why: 'Do not argue from the Imam’s age. The point is that the guide said to be necessary has not been there to consult since 941, and Twelvers rely on fallible scholars.' },
  { id: 'arg-shia-different-quran', topicId: 'shia-sources', verdict: 'avoid', claim: 'The Shia have a different Quran from other Muslims.', why: 'They do not. A Shia reads the same Arabic text as every Sunni, and mainstream Twelver teaching for a thousand years has been that the Quran is complete.' },
  { id: 'arg-taqiyya-lying', topicId: 'shia-sources', verdict: 'avoid', claim: 'You cannot trust what a Shia tells you, because taqiyya allows him to lie.', why: 'Taqiyya is about concealing faith when in danger, not a licence to lie to outsiders. To hint that your friend is lying is unjust, and it is bearing false witness.' },
  { id: 'arg-all-but-three', topicId: 'shia-sources', verdict: 'overstated', claim: 'The Shia teach that all of Muhammad’s companions except three left Islam.', why: 'Al-Kafi has such a report, but it is about the pledge of allegiance. On the Twelver reading it charges the companions with deserting Ali and does not put them outside Islam.' },
  { id: 'arg-shia-jesus', topicId: 'shia-karbala-gospel', verdict: 'avoid', claim: 'Husayn is the Shia Jesus.', why: 'The lesson says not to say this, and not to treat Karbala as a mere illustration. Ask your friend to tell you the story and what it means to him.' },
  { id: 'arg-sunnis-karbala-crime', topicId: 'shia-karbala-gospel', verdict: 'sound', claim: 'Sunnis too regard the killing of Husayn at Karbala as a crime.', why: 'Sahih al-Bukhari records a companion saying bitterly that the people of Iraq murdered the son of the Prophet’s daughter. Hardly any Muslim you meet will defend what was done.' },
  { id: 'arg-martyr-and-sacrifice', topicId: 'shia-karbala-gospel', verdict: 'sound', claim: 'A martyr leaves an example, but Jesus offered a sacrifice for sins, once for all.', why: 'An example can stir me, but it cannot remove my guilt. Because the sacrifice was made once, it needs no yearly renewal.' },
  { id: 'arg-quranists-khalifa', topicId: 'quranist-overview', verdict: 'overstated', claim: 'Quran-only Muslims all follow Rashad Khalifa and his number 19 code.', why: 'Khalifa was the most famous Quran-only teacher in the West, but many Quran-only Muslims reject his code, his deleted verses and his claim to be a messenger.' },
  { id: 'arg-bukhari-to-quranist', topicId: 'quranist-overview', verdict: 'avoid', claim: 'Said to a Quran-only Muslim: “Sahih al-Bukhari records this about Muhammad, so you have to answer for it.”', why: 'Put the hadith away. “Sahih al-Bukhari says” means nothing to him, but every argument drawn from the Quran itself still applies in full.' },
  { id: 'arg-hadith-criticism-sound', topicId: 'quranist-overview', verdict: 'sound', claim: 'A Quran-only Muslim’s criticism of the hadith is largely sound, and a Christian can say so.', why: 'You need not defend Bukhari to anyone. It is rare for a Muslim to hear a Christian begin by agreeing with him.' },
  { id: 'arg-prayer-not-detailed', topicId: 'quranist-answering', verdict: 'sound', claim: 'The Quran commands prayer constantly but never states how many prayers there are each day or what is to be said.', why: 'It names a dawn prayer, a night prayer and “the middle prayer” and assumes the reader knows the rest. That is hard to square with a book “explained in detail”.' },
  { id: 'arg-quran-no-better-than-hadith', topicId: 'quranist-answering', verdict: 'overstated', claim: 'The Quran reached us in exactly the way the hadith did, so there is no difference between trusting one and trusting the other.', why: 'Grant the real difference: the Quran was written early and recited by the whole community. But who collected it, how, and from what is known only from the same reports.' },
  { id: 'arg-khalifa-deleted-verses', topicId: 'quranist-answering', verdict: 'sound', claim: 'Rashad Khalifa set out to follow the Quran alone and ended by deleting two of its verses.', why: 'He removed them to fit his number code and named himself God’s Messenger of the Covenant. In his case the Quran alone did not stay alone.' },
  { id: 'arg-atham-fifteen-months', topicId: 'ahmadiyya-overview', verdict: 'sound', claim: 'Mirza Ghulam Ahmad announced that whichever side in his debate with the Christian Abdullah Atham followed falsehood would be cast into Hell within fifteen months, and when the time ended Atham was alive and still a Christian.', why: 'The facts come from the Ahmadiyya community’s own publications. The revelation carried the condition “that he does not return to the Truth”, so be ready for the Ahmadi explanations.' },
  { id: 'arg-every-ahmadi-prophet', topicId: 'ahmadiyya-overview', verdict: 'overstated', claim: 'Every Ahmadi believes that Mirza Ghulam Ahmad was a prophet.', why: 'The main community does. The smaller Lahore branch teaches that he was a reformer and the promised Messiah but not a prophet, so ask which community your friend belongs to.' },
  { id: 'arg-ahmadis-not-muslims', topicId: 'ahmadiyya-overview', verdict: 'avoid', claim: 'Ahmadis are not real Muslims.', why: 'Do not rule on who is a Muslim; that is an argument among Muslims. The Christian’s question is whether this man spoke from God.' },
  { id: 'arg-no-survival-source', topicId: 'ahmadiyya-jesus-in-india', verdict: 'sound', claim: 'No ancient writer, Christian, Jewish or pagan, says that Jesus was crucified and survived.', why: 'Historians of every outlook treat the death of Jesus by crucifixion as one of the most certain facts about him.' },
  { id: 'arg-kashmir-is-notovitch', topicId: 'ahmadiyya-jesus-in-india', verdict: 'overstated', claim: 'The Ahmadi teaching that Jesus died in Kashmir is just Notovitch’s forged Tibetan gospel.', why: 'They are separate claims that contradict each other: Notovitch has Jesus in India before his ministry and dying in Palestine. Ahmad did, though, cite the Tibetan gospel in 1898.' },
  { id: 'arg-yuz-asaf-buddha', topicId: 'ahmadiyya-jesus-in-india', verdict: 'sound', claim: 'The story of Yuz Asaf, the man buried in the Srinagar shrine, has been traced to a legend about the Buddha.', why: 'Budhasaf, the Buddhist title Bodhisattva, was miscopied in Arabic script as Yuzasaf. The Ahmadiyya community’s own website grants that the name “may be of Buddhist derivation”.' },
  { id: 'arg-how-could-anyone', topicId: 'noi-overview', verdict: 'avoid', claim: 'How could anyone believe a story as strange as Yakub?', why: 'Do not begin there. Begin by asking what the Nation gave its members: dignity, discipline and a grievance that is true.' },
  { id: 'arg-noi-outside-islam', topicId: 'noi-overview', verdict: 'sound', claim: 'Sunni and Shia Muslims regard the Nation of Islam’s teachings as outside Islam.', why: 'The Quran says of Allah, “There is nothing like unto Him”, and calls Muhammad the last of the prophets. Elijah Muhammad’s best-known minister and his own son both left his doctrine.' },
  { id: 'arg-all-hold-yakub', topicId: 'noi-overview', verdict: 'overstated', claim: 'Everyone who sells The Final Call believes that white people are devils bred by Yakub.', why: 'Some hold every word of Elijah Muhammad’s teaching. Others value the discipline and the pride and have hardly thought about Yakub, so find out before you answer.' },
  { id: 'arg-ethiopia-before-england', topicId: 'noi-answering', verdict: 'sound', claim: 'Ethiopia had a Christian king more than two hundred years before the first missionaries reached the English.', why: 'The missionaries reached the English in 597. Africa did not first receive the gospel from Europe; much of Europe received it later than Africa did.' },
  { id: 'arg-ancestors-were-christians', topicId: 'noi-answering', verdict: 'overstated', claim: 'The ancestors of black Americans were Christians long before the slave ships came.', why: 'The faith was at home in Africa centuries before the slave ships. But most black Americans’ ancestors came from West Africa, and this history does not show that they were Christians.' },
  { id: 'arg-god-as-man-absurd', topicId: 'noi-answering', verdict: 'avoid', claim: 'The idea that God could appear as a man is absurd.', why: 'Christians also say that God came among us in the flesh, so we cannot call the idea absurd. The difference is in what is claimed and what supports it.' },
  { id: 'arg-druze-hakim-god', topicId: 'druze-overview', verdict: 'avoid', claim: 'Said to a Druze: “You believe the caliph al-Hakim was God.”', why: 'Outside scholars report something like this, but they do not all agree and the Druze scriptures are not given to outsiders. Do not tell a Druze what he believes. Ask him.' },
  { id: 'arg-no-druze-muslim', topicId: 'druze-overview', verdict: 'overstated', claim: 'No Druze counts himself a Muslim.', why: 'Many Muslims have not counted the Druze faith as Islam, and many Druze do not call themselves Muslims. But some do, and Lebanon counts the Druze among its Muslim communities.' },
  { id: 'arg-rebirth-and-guilt', topicId: 'druze-overview', verdict: 'sound', claim: 'Rebirth cannot deal with guilt, because on the Druze account itself the judgment still waits at the end of all the lives.', why: 'Scripture says that man is appointed to die once and after that to face judgment. The Christian hope is resurrection, not return.' },
  { id: 'arg-alawite-assad', topicId: 'alawites', verdict: 'avoid', claim: 'Alawites ran Syria under the Assads, so an Alawite owes you an explanation for that government.', why: 'Do not ask him to account for it. Many Alawites stayed poor, and he may be blamed for the crimes of a government that did little for him.' },
  { id: 'arg-alawites-ali-god', topicId: 'alawites', verdict: 'overstated', claim: 'It is certain that all Alawites today believe Ali is God.', why: 'Published accounts do report that Ali is treated as a manifestation of God. But the teaching is secret, some sources are hostile, and it is uncertain how far it is still held; most Alawites were never taught it.' },
  { id: 'arg-call-them-nusayris', topicId: 'alawites', verdict: 'avoid', claim: 'The proper name for the Alawites is Nusayris.', why: 'Alawite writers reject the old name as one used by their enemies, and it is still thrown at them as abuse. Do not use it yourself.' },
  { id: 'arg-alevis-all-islam', topicId: 'alevis', verdict: 'overstated', claim: 'All Alevis see their faith as a form of Islam.', why: 'Alevis themselves disagree. Some say Alevism is the true, inward Islam, some that it is a faith in its own right, and some that it is a culture and not a religion.' },
  { id: 'arg-perfect-human', topicId: 'alevis', verdict: 'sound', claim: 'The Alevi ideal is the perfect human being, and the New Testament says that one man has reached it.', why: 'Jesus “committed no sin, and no deceit was found in His mouth”. Ask your friend who has ever reached the ideal.' },
  { id: 'arg-not-all-paths-one', topicId: 'alevis', verdict: 'sound', claim: 'Christians cannot agree that all paths are one, because Jesus said that no one comes to the Father except through him.', why: 'Say it without heat. To a people who have been killed by men sure of their own truth, how you say it matters as much as what you say.' },
  // Islam track
  { id: 'arg-practice-from-hadith', topicId: 'islam-understanding', verdict: 'sound', claim: 'Most of Islamic practice, such as how to pray, comes from the hadith and not from the Quran alone.', why: 'The Sunnah, the example of Muhammad, is recorded in the hadith. The Quran itself commands obedience to the Messenger.' },
  { id: 'arg-quran-rejects-jesus', topicId: 'islam-understanding', verdict: 'overstated', claim: 'The Quran rejects everything Christians believe about Jesus.', why: 'It denies that he is the Son of God and that he was crucified, but it affirms his virgin birth, calls him the Messiah and credits him with miracles. That is common ground.' },
  { id: 'arg-weak-hadith', topicId: 'islam-understanding', verdict: 'avoid', claim: 'This saying is in one of the hadith collections, so a Muslim has to accept it, even though it is graded weak.', why: 'Muslim scholars grade each hadith as authentic, good or weak, and a weak one carries no real weight. Do not build an argument on a weak report.' },
  { id: 'arg-quran-all-groups', topicId: 'islam-branches', verdict: 'sound', claim: 'Arguments drawn from the Quran itself apply to nearly every Muslim group, Sunni or Shia.', why: 'Nearly all of them accept the Quran. The Druze, who have their own scripture besides, and many Alevis are partial exceptions.' },
  { id: 'arg-bukhari-every-muslim', topicId: 'islam-branches', verdict: 'overstated', claim: 'Every Muslim has to accept what Sahih al-Bukhari says.', why: 'That works with Sunnis, the large majority. Shia Muslims have their own hadith collections, and Quran-only Muslims reject the hadith altogether.' },
  { id: 'arg-two-qurans', topicId: 'islam-branches', verdict: 'avoid', claim: 'Sunni and Shia Muslims cannot even agree on the Quran.', why: 'They share one Quran, as Christians share one New Testament. What they disagree about is which accounts of Muhammad’s words and deeds are genuine.' },
  { id: 'arg-judge-by-gospel', topicId: 'islam-dilemma', verdict: 'sound', claim: 'The Quran tells the Christians of Muhammad’s own day to judge by the Gospel they had.', why: 'Quran 5:47 says, “Let the People of the Gospel judge by what Allah has revealed therein.” It treats that Gospel as available and authoritative.' },
  { id: 'arg-none-can-change', topicId: 'islam-dilemma', verdict: 'overstated', claim: 'The Quran’s verses that no one can change Allah’s words are plainly about the written scriptures.', why: 'Expect the reply that commentators such as Ibn Kathir read most of these verses as speaking of God’s decrees and promises, not of written scripture.' },
  { id: 'arg-what-was-before-it', topicId: 'islam-dilemma', verdict: 'avoid', claim: 'The Quran says it confirms “what was before it”, so build your case on that phrase.', why: 'A Muslim may take that phrase to mean “earlier in time”. Lean on the clearer verses, which say the Quran confirms what is “with you” and “with them”.' },
  { id: 'arg-no-creed-mary', topicId: 'islam-misunderstands-christianity', verdict: 'sound', claim: 'No Christian creed has ever taught that the Trinity is God, Jesus and Mary.', why: 'The Trinity is Father, Son and Holy Spirit. As Quran 5:116 and 5:73 are often read, the Quran denies a Trinity Christians never believed.' },
  { id: 'arg-quran-lists-three', topicId: 'islam-misunderstands-christianity', verdict: 'overstated', claim: 'The Quran states outright that the Trinity is Allah, Jesus and Mary.', why: 'No verse lists the three. The case rests on how the Quran argues: straight after condemning “the third of three”, it says the Messiah and his mother both ate food.' },
  { id: 'arg-moses-nephew', topicId: 'islam-misunderstands-christianity', verdict: 'avoid', claim: 'The Quran’s author believed that Jesus was the nephew of Moses.', why: 'The Quran places messengers between Moses and Jesus, so the lesson does not claim this. Raise “sister of Aaron” as a question, not as a proven error.' },
  { id: 'arg-commentators-differ', topicId: 'islam-crucifixion', verdict: 'sound', claim: 'The classical Muslim commentators did not agree on who was crucified in place of Jesus.', why: 'Al-Tabari records several accounts, and none names a source from the time of Jesus. Ask: who was crucified, and how do you know?' },
  { id: 'arg-quran-says-judas', topicId: 'islam-crucifixion', verdict: 'overstated', claim: 'The Quran says that Judas was crucified in place of Jesus.', why: 'The Arabic of Quran 4:157 does not mention a substitute. Judas is one of several accounts in the commentators, and they contradict one another.' },
  { id: 'arg-mutawaffika', topicId: 'islam-crucifixion', verdict: 'overstated', claim: 'The word used in Quran 3:55 for God taking Jesus can only mean death.', why: 'It is the verb the Quran most often uses for God taking people in death, but the Quran also uses it of sleep.' },
  { id: 'arg-forbade-women-children', topicId: 'islam-muhammad-warfare', verdict: 'sound', claim: 'Muhammad forbade the killing of women and children in war.', why: 'Sahih al-Bukhari 3015 records it, and it is fair to acknowledge it. But rules for conducting war do not change the fact that he led wars to spread his rule.' },
  { id: 'arg-none-defensive', topicId: 'islam-muhammad-warfare', verdict: 'overstated', claim: 'None of Muhammad’s battles was fought in self-defence.', why: 'Some early battles can be described as defensive. The point is that Quran 9:29 commands fighting the People of the Scripture because they do not believe.' },
  { id: 'arg-muslims-violent', topicId: 'islam-muhammad-warfare', verdict: 'avoid', claim: 'Muhammad’s wars show what ordinary Muslims are like.', why: 'The lesson is about Muhammad’s example, not about ordinary Muslims, many of whom are peaceful people troubled by violence done in Islam’s name.' },
  { id: 'arg-no-bound-quran', topicId: 'islam-quran-oral', verdict: 'sound', claim: 'There was no complete, bound Quran when Muhammad died.', why: 'Some passages had been written on whatever was at hand. Zaid bin Thabit later gathered the text from palm stalks, stones and the men who knew it by heart.' },
  { id: 'arg-telephone', topicId: 'islam-quran-oral', verdict: 'avoid', claim: 'The Quran was handed down like a game of telephone.', why: 'Be fair: communal recitation is more stable than one person whispering to the next, because many people check each other.' },
  { id: 'arg-umar-fear', topicId: 'islam-quran-oral', verdict: 'overstated', claim: 'Umar’s alarm after the battle of Yamama proves that part of the Quran was lost.', why: 'The fear does not prove a loss. It shows what the leading companions believed about memory: that it was not enough.' },
  { id: 'arg-uthman-burned', topicId: 'islam-quran-preservation', verdict: 'sound', claim: 'Sahih al-Bukhari reports that Uthman sent out one text of the Quran and ordered all the other copies burned.', why: 'So the preservation of today’s text is the preservation of Uthman’s edition. The readings of the rival copies survive mainly as later reports.' },
  { id: 'arg-ibn-masud-never', topicId: 'islam-quran-preservation', verdict: 'overstated', claim: 'Ibn Mas’ud never accepted Uthman’s text.', why: 'He protested, but later Muslim writers report that he was reconciled. His protest still shows that his copy and Zaid’s were not the same.' },
  { id: 'arg-we-have-originals', topicId: 'islam-quran-preservation', verdict: 'avoid', claim: 'Christians have the original manuscripts of the New Testament, and Muslims have lost theirs.', why: 'Neither side has originals. What Christians have is writings from the first century that were copied freely, with no one able to gather them in and edit them.' },
  { id: 'arg-quran-own-test', topicId: 'islam-quran-consistency', verdict: 'sound', claim: 'The Quran itself says that a book from anyone but Allah would contain much contradiction.', why: 'That is Quran 4:82. The aim is to show that the Quran fails a test it set for itself.' },
  { id: 'arg-eight-days', topicId: 'islam-quran-consistency', verdict: 'overstated', claim: 'The Quran says creation took eight days, and Muslims have no answer to that.', why: 'Commentators say the four days include the first two, and harmonising is legitimate. The point is that Quran 4:82 stakes the Quran’s divine origin on the absence of contradiction.' },
  { id: 'arg-long-list', topicId: 'islam-quran-consistency', verdict: 'avoid', claim: 'The more contradictions in the Quran you can list, the stronger your case.', why: 'The aim is not to win with a long list. A few clear examples are better than many weak ones.' },
  { id: 'arg-ezra-son', topicId: 'islam-quran-history', verdict: 'sound', claim: 'No Jewish source records any Jewish group saying that Ezra is the son of God.', why: 'Yet Quran 9:30 says the Jews say it. The Jewish scriptures present Ezra as a scribe and priest.' },
  { id: 'arg-haman-name', topicId: 'islam-quran-history', verdict: 'overstated', claim: 'The name Haman in Pharaoh’s court is enough by itself to prove an error in the Quran.', why: 'Two men can share a name, and one case would not prove much. The argument is the name together with the office and the tower, as part of a pattern.' },
  { id: 'arg-son-unnamed', topicId: 'islam-quran-history', verdict: 'sound', claim: 'The Quran never names the son Abraham was told to sacrifice.', why: 'Genesis names Isaac, and the New Testament says the same. So the only texts that name the son say Isaac.' },
  { id: 'arg-periklytos', topicId: 'islam-muhammad-in-bible', verdict: 'sound', claim: 'No known Greek manuscript of John reads periklytos, “praised one”, where our Bibles have parakletos.', why: 'They read parakletos, helper or advocate. And the context, the Spirit of truth dwelling in the disciples, does not fit Muhammad whatever the word.' },
  { id: 'arg-brothers-never', topicId: 'islam-muhammad-in-bible', verdict: 'overstated', claim: 'In Deuteronomy the word “brothers” never refers to anyone outside Israel.', why: 'Edom is called a brother there, and that should be granted. But Deuteronomy never calls the Ishmaelites Israel’s brothers, and the prophet comes “from your midst”.' },
  { id: 'arg-no-miracles', topicId: 'islam-muhammad-in-bible', verdict: 'avoid', claim: 'Islam’s sources never credit Muhammad with a miracle.', why: 'The hadith report the splitting of the moon; do not pretend they don’t. Point instead to the Quran, which answers requests for a sign by saying he is only a warner.' },
  { id: 'arg-abu-bakr-wager', topicId: 'islam-quran-challenge', verdict: 'sound', claim: 'By the hadith’s account, Abu Bakr’s wager on a Roman victory ran out before the Romans won.', why: 'The Meccans collected their winnings before the Romans prevailed, in the seventh year by one report. A prophecy whose first hearers could not tell when it would come true is hard to call precise.' },
  { id: 'arg-deliberate-fraud', topicId: 'islam-quran-challenge', verdict: 'avoid', claim: 'Muhammad was a deliberate fraud who knew he was making it all up.', why: 'The lesson does not accuse him of a calculated fraud. A man can be sincere and mistaken, and suffering for a message shows only that he believed it.' },
  { id: 'arg-eloquence-not-truth', topicId: 'islam-quran-challenge', verdict: 'sound', claim: 'A beautifully written statement can still be false, so the Quran’s eloquence does not show that it is true.', why: 'The real test is whether the Quran’s claims are true: about Jesus, about the Bible, about history.' },
  { id: 'arg-big-bang-late', topicId: 'islam-scientific-miracles', verdict: 'sound', claim: 'No classical Muslim scholar read Quran 21:30 as the Big Bang until after the theory was known.', why: 'If a prediction is only recognised after the discovery, it is not a prediction.' },
  { id: 'arg-muddy-spring', topicId: 'islam-scientific-miracles', verdict: 'overstated', claim: 'Quran 18:86 proves that the Quran teaches the sun sets in a muddy spring.', why: 'Reading the verse as what the traveller saw is possible, and classical commentators read it so. Rest the case on Muhammad’s own explanation of the sun in Sahih al-Bukhari 3199.' },
  { id: 'arg-bible-science', topicId: 'islam-scientific-miracles', verdict: 'avoid', claim: 'The Bible has scientific miracles of its own: Job says God “hangs the earth upon nothing”.', why: 'The lesson does not call that a scientific miracle. Christians do not claim that the Bible proves itself by hidden science.' },
  { id: 'arg-only-jesus-word', topicId: 'islam-jesus-more-than-prophet', verdict: 'sound', claim: 'The Quran gives the title “His word” to Jesus and to no one else.', why: 'Adam too was made by the command “Be”, yet the Quran never calls Adam God’s Word. Use this as a conversation opener, not a proof.' },
  { id: 'arg-miracles-prove-god', topicId: 'islam-jesus-more-than-prophet', verdict: 'overstated', claim: 'The miracles of Jesus prove that he is God.', why: 'Miracles alone do not prove deity. The issue is the claims Jesus made alongside them: he forgave sins, accepted worship and said he would judge the world.' },
  { id: 'arg-soul-from-him', topicId: 'islam-jesus-more-than-prophet', verdict: 'avoid', claim: 'The Quran calls Jesus “a soul from Him”, and that sets him apart from every other man.', why: 'Adam too receives God’s breath in the Quran. Rest the point on “word”, not on “a soul from Him”.' },
  { id: 'arg-early-creed', topicId: 'islam-cross-resurrection', verdict: 'sound', claim: 'Paul passes on an early creed that Christ died, was buried and was raised, and names witnesses who were still living.', why: 'It is in 1 Corinthians 15:3-6. He says most of the five hundred who saw the risen Jesus were still alive, which invites checking.' },
  { id: 'arg-pierced-settles', topicId: 'islam-cross-resurrection', verdict: 'overstated', claim: 'The Hebrew text of Psalm 22:16 says “pierced”, and that word proves the psalm is about the crucifixion.', why: 'The standard Hebrew text reads “like a lion”; “pierced” follows the ancient Greek translation and an early Hebrew manuscript. Whichever is original, the rest of the psalm still fits the crucifixion.' },
  { id: 'arg-isaiah53-always', topicId: 'islam-cross-resurrection', verdict: 'overstated', claim: 'Jewish teachers have always read Isaiah 53 as being about the Messiah.', why: 'Reading it of the Messiah is found in Jewish sources. But the reading that makes the servant the nation is old as well, and has been the usual Jewish reading since the Middle Ages.' },
  { id: 'arg-even-muhammad', topicId: 'islam-gospel-of-grace', verdict: 'sound', claim: 'Muhammad said that not even he would be saved by his deeds, but only if Allah showed him mercy.', why: 'Sahih al-Bukhari 6463 and Sahih Muslim 2816 record it. If even his deeds were not enough, what hope does anyone have by deeds?' },
  { id: 'arg-allah-never-loves', topicId: 'islam-gospel-of-grace', verdict: 'overstated', claim: 'The Quran never speaks of Allah loving anyone.', why: 'It speaks of Allah loving those who follow the Messenger and the doers of good. In these verses his love is a response to obedience.' },
  { id: 'arg-allah-no-mercy', topicId: 'islam-gospel-of-grace', verdict: 'avoid', claim: 'The God of Islam is not merciful, and the God of the Bible is.', why: 'Both faiths say God is merciful. The question is how a just God can show mercy without ignoring justice.' },
  { id: 'arg-constantine-no-part', topicId: 'islam-trinity', verdict: 'overstated', claim: 'The emperor Constantine had nothing to do with what was decided at Nicaea.', why: 'He called the council, pressed for agreement and afterwards exiled Arius. But it was the bishops who condemned Arius’s teaching, and the doctrine outlasted the emperors.' },
  { id: 'arg-humanity-incarnation', topicId: 'islam-deity-objections', verdict: 'sound', claim: 'Passages that show Jesus praying, growing tired or dying do not disprove his deity.', why: 'Christianity teaches that the eternal Son became fully human while remaining fully God. Such passages confirm the incarnation.' },
  { id: 'arg-1-john-5-20', topicId: 'islam-deity-objections', verdict: 'overstated', claim: '1 John 5:20 calls Jesus “the true God”, and no one can read it any other way.', why: 'Many scholars defend that reading, but some take the words to refer to the Father. Nothing rests on that one verse: John 1:1 and John 20:28 are plain.' },
  { id: 'arg-god-never-says', topicId: 'islam-deity-objections', verdict: 'avoid', claim: 'God never speaks in so blunt a way as “I am God, worship me”.', why: 'Do not claim that: in Quran 20:14 Allah says, “Indeed, I am Allah. There is no deity except Me, so worship Me.” Show instead that Jesus speaks as God speaks.' },
  { id: 'arg-ezekiel-18', topicId: 'islam-atonement', verdict: 'sound', claim: 'Ezekiel 18 is about people being punished for their parents’ sins, not about a willing substitute.', why: 'The Israelites were blaming their ancestors for their own judgment. Jesus was not forced; he laid down his life voluntarily.' },
  { id: 'arg-quran-teaches-atonement', topicId: 'islam-atonement', verdict: 'overstated', claim: 'The Quran itself teaches atonement for sin by sacrifice, in the story of Abraham’s son.', why: 'It contains the idea of a life ransomed by a substitute sacrifice. But Muslims keep the yearly sacrifice as a commemoration and not as atonement for sin.' },
  { id: 'arg-garments-of-skin', topicId: 'islam-atonement', verdict: 'avoid', claim: 'God clothed Adam in skins, which proves that a sacrifice was made for his sin.', why: 'Genesis 3:21 does not spell that out, and the lesson says it will not lean on it.' },
  { id: 'arg-right-hand', topicId: 'islam-bible-corruption', verdict: 'sound', claim: 'The leaders in Jerusalem, Peter, John and James, accepted Paul and his message.', why: 'They gave him the right hand of fellowship (Galatians 2:9), and Paul says he and they preached the same gospel.' },
  { id: 'arg-ibn-hazm-first', topicId: 'islam-bible-corruption', verdict: 'overstated', claim: 'Nobody said the text of the Bible had been altered until Ibn Hazm, four centuries after Muhammad.', why: 'Ibn Hazm argued it at length, but the charge of altering the text was also made early. The earliest commentators mostly speak of hiding or misreading.' },
  { id: 'arg-nothing-added', topicId: 'islam-bible-corruption', verdict: 'avoid', claim: 'Nothing was ever added to any copy of the New Testament.', why: 'Mark 16:9-20 and the story of the woman caught in adultery are not in the earliest manuscripts. Concede it honestly: Bibles footnote them, and no doctrine depends on them.' },
  { id: 'arg-reason-to-read', topicId: 'islam-sharing-the-gospel', verdict: 'sound', claim: 'The Quran tells the people of the Gospel to judge by it, so a Muslim has every reason to read a Gospel.', why: 'That is Quran 5:47. Offer a Gospel, suggest starting with Luke or John, and offer to read it with them.' },
  { id: 'arg-apostasy-everywhere', topicId: 'islam-sharing-the-gospel', verdict: 'overstated', claim: 'Every Muslim country puts to death those who leave Islam.', why: 'In the hadith and in classical Islamic law the penalty is death. Today only about ten states have it in law, and a growing number of Muslim scholars reject it, though many still uphold it.' },
  { id: 'arg-just-stubborn', topicId: 'islam-sharing-the-gospel', verdict: 'avoid', claim: 'A Muslim who hears the gospel and still hesitates is just being stubborn.', why: 'For many Muslims, following Jesus means losing family, community, marriage or work, and in some places facing violence. Do not treat hesitation as mere stubbornness.' },
  // Books outside the Bible, and the readings of the Quran
  { id: 'arg-luther-kept-apocrypha', topicId: 'old-testament-apocrypha', verdict: 'sound', claim: 'Luther did not take the Apocrypha out of the Bible: his German Bible of 1534 printed those books between the Testaments.', why: 'He gathered them under a heading saying they are not held equal to the sacred Scriptures but are useful and good to read.' },
  { id: 'arg-nt-never-apocrypha', topicId: 'old-testament-apocrypha', verdict: 'overstated', claim: 'The New Testament never quotes or even alludes to the Apocrypha.', why: 'No New Testament writer quotes one of these books with a formula such as “it is written”. But the writers knew them: most commentators see the martyrs of 2 Maccabees behind Hebrews 11:35.' },
  { id: 'arg-trent-added', topicId: 'old-testament-apocrypha', verdict: 'avoid', claim: 'Rome added the Apocrypha to the Bible at the Council of Trent in 1546.', why: 'The lesson says not to say this. These books had been in the Latin Bible for more than a thousand years before Trent.' },
  { id: 'arg-mary-not-wife', topicId: 'other-gospels', verdict: 'sound', claim: 'Neither the Gospel of Philip nor the Gospel of Mary says in so many words that Jesus and Mary Magdalene were married.', why: 'Philip calls her the Lord’s “companion”, a word that can mean a partner of several kinds, and the word saying where he kissed her is lost in a hole in the papyrus.' },
  { id: 'arg-church-never-suppressed', topicId: 'other-gospels', verdict: 'overstated', claim: 'The church never suppressed any of the other gospels.', why: 'In the second century Christians were an illegal minority with no power to suppress anything, and they answered these books in open argument. But later church leaders did discourage and sometimes destroy them, and denying it loses trust.' },
  { id: 'arg-all-forgeries', topicId: 'other-gospels', verdict: 'avoid', claim: 'The other gospels are all forgeries.', why: 'The lesson says not to call them forgeries as a class. Some carry a false name, some carry no name, and some are honest collections of legend, so say what is known about each.' },
  { id: 'arg-barnabas-denies-messiah', topicId: 'edges-of-the-canon', verdict: 'sound', claim: 'The Gospel of Barnabas has Jesus deny that he is the Messiah, while the Quran calls Jesus the Messiah.', why: 'In chapter 42 he says “I am not the Messiah”, and the book gives that title to Muhammad. The Quran speaks of “the Messiah, Jesus, the son of Mary” (Quran 3:45).' },
  { id: 'arg-barnabas-date-proved', topicId: 'edges-of-the-canon', verdict: 'overstated', claim: 'Scholars have proved that the Gospel of Barnabas was written in the fourteenth century.', why: 'Scholars who have studied it place it long after the time of Jesus, but they differ on how long: some say the fourteenth century, others the sixteenth or early seventeenth. Present the dating as the judgement of scholars and give the evidence.' },
  { id: 'arg-barnabas-sneer', topicId: 'edges-of-the-canon', verdict: 'avoid', claim: 'The Gospel of Barnabas is an obvious fake, and nobody sincere could take it for the true Gospel.', why: 'The lesson says not to sneer at it. Many sincere people have been told that it is the lost Gospel, so present the dating as the judgement of scholars and give the evidence.' },
  { id: 'arg-readings-in-print', topicId: 'islam-quran-readings', verdict: 'sound', claim: 'Muslim scholars accept several readings of the Quran, and printed copies in more than one of them are in use today.', why: 'Hafs, Warsh, Qalun and al-Duri are all recited and printed today. They differ in a great many details of pronunciation and in some words.' },
  { id: 'arg-readings-not-from-god', topicId: 'islam-quran-readings', verdict: 'overstated', claim: 'The different readings prove that the Quran is not from God.', why: 'They tell only against a narrower claim: that perfect, uniform preservation, down to the letter, proves the book divine. Which message is true cannot be settled by counting letters.' },
  { id: 'arg-readings-corrupt', topicId: 'islam-quran-readings', verdict: 'avoid', claim: 'The different readings show that the Quran is hopelessly corrupt.', why: 'The lesson says you are not saying this. The readings agree on the overwhelming bulk of the text, and none of the differences overturns a Muslim doctrine.' },
  { id: 'arg-shortest-bible-inside', topicId: 'canons-compared', verdict: 'sound', claim: 'Every book in a Protestant Bible is also in a Catholic and an Orthodox Bible, so the shortest Christian Bible sits inside the longer ones.', why: 'All the main traditions share the same twenty-seven New Testament books and the whole Hebrew Bible. The differences are additions at one edge of the Old Testament.' },
  { id: 'arg-nothing-turns-on-books', topicId: 'canons-compared', verdict: 'overstated', claim: 'Nothing at all turns on the books that Catholics have and Protestants do not.', why: 'Some things do: the Catholic Catechism quotes 2 Maccabees when it explains prayer for the dead. What does not turn on them is the centre of the faith, which is taught in books every Christian tradition receives.' },
  { id: 'arg-their-bible-false', topicId: 'canons-compared', verdict: 'avoid', claim: 'Catholic, Orthodox and Ethiopian Bibles are wrong, because those churches added false books to Scripture.', why: 'The lesson says never to call their Bible wrong or their books false. Say what you hold and why, and name the weak points in your own case first.' },
];

